def RootMSE(y_pred: np.ndarray, y_truth: np.ndarray) -&gt; float:
    return 0.0
def AVE(y_pred: np.ndarray, y_truth: np.ndarray) -&gt; float:
    return 0.0
def r_squared(y_pred: np.ndarray, y_truth: np.ndarray) -&gt; float:
    return 0.0

